import{t as e}from"./jsx-runtime-lw2jiZar.js";import{t}from"./archive-9a0QBsx1.js";import{C as n,D as r,E as i,H as a,M as o,N as s,O as c,P as l,T as u,_ as d,j as f,k as p,l as m,n as h,o as g,t as _,v}from"./shared-DoR5oW6-.js";import{t as y}from"./CodeEditor-BZlrvoTL.js";var b=e();function x({module:e}){return(0,b.jsxs)(s,{children:[(0,b.jsx)(o,{variant:`project`,chip:e??`Блок 5 · Функции и поток данных`,title:`22.1. Состояние запуска и изменяемый default`,intro:`Передадим знакомому Planner состояние одного запуска и вернём его после exit. Для этого сначала разберём значение по умолчанию, или default, и отличим отсутствие списка от намеренно пустого контейнера.`,tags:[{icon:(0,b.jsx)(t,{size:14}),label:`состояние одного запуска`},{icon:(0,b.jsx)(a,{size:14}),label:`None и тот же список`}]}),(0,b.jsxs)(l,{number:`00`,title:`Откуда берётся состояние одного запуска`,children:[(0,b.jsx)(c,{children:`Раньше мы изучили ссылки, мутацию списков и словарей, параметры и return. Знакомый run пока сам создаёт список задач внутри функции, поэтому вызывающий код не может передать ему подготовленное состояние и получить итог после выхода.`}),(0,b.jsx)(p,{variant:`connected`,items:[{title:`Точка старта`,description:`Мы понимаем, как функция получает объект через параметр, а run создаёт свой список.`},{title:`Новый вопрос`,description:`Как отделить отсутствие списка от намеренно пустого и не разделить один default между запусками?`},{title:`Результат`,description:`Изменим договор run: один контейнер проходит команды и возвращается после exit.`}]}),(0,b.jsx)(`p`,{children:`Сначала разберём время создания default, затем отличим None от пустого списка и проследим выбранное состояние через команды. Так мы поймём не только какую строку изменить, но и почему следующий запуск не должен наследовать случайное содержимое прошлого.`})]}),(0,b.jsxs)(l,{number:`01`,title:`Изменяемый default создаётся при определении функции`,children:[(0,b.jsx)(c,{children:`Default, то есть значение по умолчанию, подставляется, когда аргумент пропущен. Python вычисляет это выражение при выполнении определения def. Если выражение создаёт список, функция сохраняет один список; каждый вызов без аргумента получает ссылку на этот объект, а не новую копию.`}),(0,b.jsx)(y,{caption:`Два вызова без аргумента`,code:`def remember_tag(tag, tags=[]):
    tags.append(tag)
    return tags

print(remember_tag("SQL"))
print(remember_tag("Git"))`}),(0,b.jsxs)(`p`,{children:[`На экране появятся строки `,(0,b.jsx)(`code`,{children:`['SQL']`}),` и `,(0,b.jsx)(`code`,{children:`['SQL', 'Git']`}),`. Первый вызов меняет список, который создал default. Второй получает его же и добавляет новую строку. Если мы сохраним ссылку на список после первого вызова, последующая мутация будет видна и через эту ссылку.`]}),(0,b.jsx)(v,{code:`def remember_tag(tag, tags=[]):
    tags.append(tag)
    return tags

print(remember_tag("SQL"))
print(remember_tag("Git"))`,steps:[{line:0,note:`При выполнении def создаётся одна функция и один список default.`,vars:{tags:`→ []`}},{line:4,note:`Первый вызов пропускает tags и получает список из default.`,vars:{tag:`"SQL"`,tags:`→ []`}},{line:1,note:`append меняет объект, а не создаёт новый список.`,vars:{tags:`→ ["SQL"]`}},{line:5,note:`Второй вызов без tags снова получает тот же объект.`,vars:{tags:`→ ["SQL"]`}},{line:1,note:`В список добавляется Git; теперь он содержит оба значения.`,vars:{tags:`→ ["SQL", "Git"]`}}]}),(0,b.jsx)(i,{tone:`info`,children:`Изменяемый default бывает намеренным, если контракт прямо задаёт общее накопление. Он опасен, когда мы ждём, что вызовы будут независимыми. Неизменяемое число приоритета и список состояния имеют разные риски.`}),(0,b.jsx)(`p`,{children:`Представим чашу с ручками, которую поставили на стол при открытии комнаты. Каждый, кто приходит без своей, берёт из той же чаши. В примере чаша соответствует объекту default, а вызовы без аргумента получают доступ к ней. Аналогия показывает совместное использование одного объекта, но не объясняет остальные детали устройства памяти Python.`}),(0,b.jsx)(`p`,{children:`Default не пересчитывается после вызова. Python не выполняет выражение [] заново при каждом пропущенном аргументе: один объект связан с определением функции. Явно переданный список используется вместо него только в этом вызове и не очищает общий список для следующих вызовов без аргумента. Так мы отделяем временное состояние одного вызова от намеренно общего.`})]}),(0,b.jsxs)(l,{number:`02`,title:`None отмечает отсутствующий контейнер`,children:[(0,b.jsx)(c,{children:`Чтобы не делить один изменяемый список между вызовами, мы можем использовать None как значение по умолчанию. В этом договоре None означает: готовый контейнер не передали. Функция создаёт список внутри конкретного вызова.`}),(0,b.jsx)(y,{caption:`Новый список только при отсутствии входа`,code:`def add_label(label, labels=None):
    if labels is None:
        labels = []
    labels.append(label)
    return labels`}),(0,b.jsxs)(`p`,{children:[`Вызовы `,(0,b.jsx)(`code`,{children:`add_label("draft")`}),` и `,(0,b.jsx)(`code`,{children:`add_label("review")`}),` получат каждый свой новый список. Они не используют общий контейнер. Если мы передадим заранее созданный список, функция изменит его и вернёт ту же ссылку. None не является пустой коллекцией и не хранит в себе задачи: это отдельное значение для обозначения отсутствующего входа.`]}),(0,b.jsx)(u,{question:`Какой договор сохраняет независимые обычные вызовы и переданный контейнер?`,left:{title:`Общий изменяемый объект`,code:`def add_label(label, labels=[]):
    labels.append(label)
    return labels`,note:`Список из default может пережить несколько вызовов без аргумента.`},right:{title:`None как признак отсутствия`,code:`def add_label(label, labels=None):
    if labels is None:
        labels = []
    labels.append(label)
    return labels`,note:`Новый список создаётся для пропущенного аргумента, переданный остаётся тем же.`},preferred:`right`,explanation:`Мы создаём новый контейнер только в ветке, где аргумента нет. Явно переданный список не подменяется.`}),(0,b.jsx)(`p`,{children:`Здесь полезна аналогия с формой заказа на коробку. Незаполненное поле означает, что для заказа выдадут новую коробку; переданная пустая коробка всё равно принадлежит этому заказу, и её не следует подменять. Поле соответствует аргументу, а коробка контейнеру. Решение в программе принимает проверка None, а не размер списка.`}),(0,b.jsx)(`p`,{children:`В сигнатуре labels=None пропуск аргумента и явная передача None приводят к одному значению. Для нашего договора это намеренно: оба варианта означают, что входного списка нет, поэтому функция начинает с нового. Список задач всегда является списком или отсутствует. В другой задаче, где None допустим как настоящие данные, понадобился бы другой способ заметить пропуск; здесь это усложнение не нужно.`})]}),(0,b.jsxs)(l,{number:`03`,title:`Пустой список тоже является входом`,children:[(0,b.jsx)(c,{children:`Пустой список может быть намеренным состоянием. Вызывающий код мог заранее создать его и сохранить ссылку, чтобы Planner заполнил именно этот объект. Поэтому проверка истинности отвечает не на тот вопрос: она объединяет отсутствующее значение и существующий пустой список.`}),(0,b.jsx)(d,{code:`def choose(items=None):
    if not items:
        items = []
    return items

provided = []
selected = choose(provided)
print(selected is provided, provided)`,output:`False []`,hint:`Проследим отдельно исходный объект provided и локальное имя items после условия.`}),(0,b.jsxs)(`p`,{children:[`Условие выполняется, потому что пустой список считается ложным. Имя `,(0,b.jsx)(`code`,{children:`items`}),` связывается с новым списком, и исходный `,(0,b.jsx)(`code`,{children:`provided`}),` не меняется. Поэтому результат говорит `,(0,b.jsx)(`code`,{children:`False`}),`, а внешний список остаётся пустым. Запись `,(0,b.jsx)(`code`,{children:`items or []`}),` также подменит намеренно переданный пустой список.`]}),(0,b.jsx)(n,{code:`def start_run(tasks=None):
    if not tasks:
        tasks = []
    return tasks`,question:`Что теряется, если вызывающий код передал пустой список?`,options:[`Связь с тем объектом, который передали`,`Возможность добавить первый элемент`,`Значение по умолчанию None`],correctIndex:0,explanation:`Проверка истинности заменяет пустой, но существующий контейнер новым объектом.`,fix:`def start_run(tasks=None):
    if tasks is None:
        tasks = []
    return tasks`}),(0,b.jsxs)(`p`,{children:[`Мы проверяем `,(0,b.jsx)(`code`,{children:`tasks is None`}),`, когда нас интересует отсутствие аргумента. Проверка `,(0,b.jsx)(`code`,{children:`tasks == []`}),`сравнивает содержимое, а условие `,(0,b.jsx)(`code`,{children:`if not tasks`}),` объединяет разные состояния. Оператор `,(0,b.jsx)(`code`,{children:`is`}),`помогает сравнить идентичность, а `,(0,b.jsx)(`code`,{children:`==`}),` содержимое: два отдельных пустых списка равны, но это не один объект. Для Planner намерение определяется наличием аргумента, а не числом задач.`]}),(0,b.jsx)(`p`,{children:`Пустой список может остаться пустым после exit и всё равно быть правильным состоянием запуска. Мы проверим, что возвращённый результат и переданный контейнер являются одним объектом. Если список заранее заполнен, его задачи остаются доступны обработчикам и коду, который вызвал run.`}),(0,b.jsx)(`p`,{children:`Перед вызовом мы можем назвать одно из трёх состояний: аргумент пропущен, передан пустой контейнер или передан заполненный. Пропуск создаёт новый список внутри run. Пустой вход проходит проверку tasks is None без замены. Заполненный список также сохраняет себя, а команды видят прежние элементы. Так мы заранее понимаем, какие ссылки нужно сравнить после завершения консольного цикла.`}),(0,b.jsx)(`p`,{children:`Проверка истинности смотрит на наличие элементов. Поэтому ошибка часто проявляется только на пустом входе: заполненный список сохраняется, а пустой подменяется. Выражение tasks or [] устроено так же. Мы проверим пустой и заполненный случаи отдельно. Для пустого важно убедиться, что после запуска сохранилась именно исходная ссылка; сравнения содержимого недостаточно.`})]}),(0,b.jsxs)(l,{number:`04`,title:`Один контейнер проходит через команды`,children:[(0,b.jsx)(c,{children:`Мы выбираем список один раз в начале run, затем передаём его каждому обработчику. handle_add может вызвать add_task и изменить этот список; следующая команда увидит изменение. list и stats тоже читают актуальное состояние, а не отдельную копию.`}),(0,b.jsx)(_,{caption:`Один список на протяжении запуска`,children:(0,b.jsxs)(g,{label:`Путь состояния от запуска до вызывающего кода`,children:[(0,b.jsx)(m,{title:`run выбирает список`,children:(0,b.jsxs)(`p`,{children:[`None: создаём новый`,(0,b.jsx)(`br`,{}),`Иначе: сохраняем переданный`]})}),(0,b.jsx)(h,{label:`передаёт тот же объект`}),(0,b.jsx)(m,{title:`Обработчики команд`,children:(0,b.jsx)(`p`,{children:`add, list и stats используют tasks`})}),(0,b.jsx)(h,{label:`после exit возвращает`}),(0,b.jsx)(m,{title:`Вызывающий код`,children:(0,b.jsx)(`p`,{children:`Получает итоговый список этого запуска`})})]})}),(0,b.jsx)(`p`,{children:`Пустой переданный список идёт по той же ветке сохранения объекта, что и заполненный.`}),(0,b.jsx)(`p`,{children:`Параметр обработчика связывается с тем же изменяемым объектом, который выбрал run. Передача списка не копирует его. Если функция меняет элемент на месте, изменение видно в списке и во внешней ссылке. Если мы создадим новый список для каждой команды, накопленное состояние пропадёт между действиями.`}),(0,b.jsx)(`p`,{children:`Представим одну папку с карточками, которую мы передаём разным людям по очереди. Папка соответствует tasks, команды соответствуют обработчикам. Добавленная карточка остаётся в этой же папке для следующего шага. Аналогия показывает общий контейнер, но не означает, что состояние сохраняется на диск или переживает остановку процесса.`}),(0,b.jsx)(i,{children:`Явная передача состояния позволяет обходиться без global и nonlocal. Зависимость каждой функции видна в её параметрах, а владелец запуска выбирает, с каким списком работать.`}),(0,b.jsx)(`p`,{children:`Выбор выполняется один раз до цикла. Без аргумента run создаёт один список для этого запуска; с аргументом локальное имя run связывается с переданным объектом. Все ветви передают дальше именно его. Обработчик добавления меняет тот же контейнер, который затем прочитает список или статистика. Если создавать новый список в каждой ветви, предыдущие действия исчезнут из следующего шага. return отдаёт наружу выбранный объект, а не копию. Если в списке лежат словари задач, он продолжает содержать ссылки на те же словари. Здесь мы сохраняем контейнер запуска и существующие ссылки на элементы; глубокое копирование каждой записи не является частью этого договора. После возврата локальное имя tasks завершит жизнь вместе с run, но объект останется доступен, если вызывающий код сохранил ссылку на него. Это состояние текущего процесса; завершение программы не сохраняет список для следующего запуска.`})]}),(0,b.jsxs)(l,{number:`05`,title:`Выход из цикла и результат функции`,children:[(0,b.jsx)(c,{children:`Команда exit завершает командный цикл, но вызывающий код должен получить итоговый список после цикла. Здесь важно различать break и return: первая команда выходит из цикла, вторая завершает функцию и возвращает значение.`}),(0,b.jsx)(y,{caption:`Фрагмент, не отдельный Planner`,code:`def process_commands(tasks, commands):
    for command in commands:
        if command == "exit":
            break
        # Здесь выполняется очередная команда с tasks
    return tasks`}),(0,b.jsxs)(`p`,{children:[`После `,(0,b.jsx)(`code`,{children:`break`}),` выполнение продолжится со строки после ближайшего цикла. Поэтому `,(0,b.jsx)(`code`,{children:`return tasks`}),`может отдать выбранный объект. Если выполнить `,(0,b.jsx)(`code`,{children:`return`}),` при первой обычной команде, весь run завершится раньше, чем мы обработаем остальные действия. Если оставить только `,(0,b.jsx)(`code`,{children:`break`}),`, список сам по себе не покинет функцию.`]}),(0,b.jsx)(`p`,{children:`Представим, что мы вышли из коридора, но можем подойти к стойке и передать папку коллеге. Выход из коридора похож на break, а передача папки из функции похожа на return. Сравнение заканчивается на различии области действия: break управляет циклом, return завершает текущий вызов функции. В этом занятии мы не добавляем обработку исключений или отдельный сценарий хранения.`}),(0,b.jsxs)(`p`,{children:[`Обычный вызов `,(0,b.jsx)(`code`,{children:`run()`}),` продолжает запускать консольный интерфейс (CLI) как раньше, даже если возвращённый список никто не сохраняет. Явный вызов с заранее подготовленным объектом даёт внешнему коду способ получить результат и проверить идентичность. После завершения процесса список остаётся только в памяти.`]}),(0,b.jsx)(`p`,{children:`break прекращает ближайший цикл, но выполнение остаётся внутри функции. После цикла мы можем завершить общую часть и вернуть результат. return немедленно завершает текущий вызов; если поставить его после обычной команды внутри цикла, остальные команды уже не выполнятся. Поэтому для обычного exit мы выходим из цикла, а состояние возвращаем после него.`}),(0,b.jsx)(`p`,{children:`Возвращаемое значение не печатается автоматически. Обычный конечный вызов run() продолжает показывать меню и сообщения команд, а вызывающий код может сохранить результат явного запуска в переменную. Вывод пользователю и передача состояния остаются разными частями договора, поэтому мы можем добавить проверяемый результат и сохранить привычные сообщения Planner.`})]}),(0,b.jsxs)(l,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,b.jsx)(c,{children:`Мы проведём короткое исследование, затем изменим жизненный цикл списка в уже существующем Planner. Прежние команды и модель задачи останутся опорой; новый объект хранения в проекте не появится.`}),(0,b.jsx)(p,{variant:`connected`,items:[{title:`Исследуем default`,description:`Сравним повторные вызовы без аргумента и объясним, почему один изменяемый объект накапливает значения.`},{title:`Обновим run`,description:`Передадим состояние и получим тот же контейнер после штатного выхода.`},{title:`Проверим Planner`,description:`Сопоставим обычные запуски, пустое и заполненное входное состояние, следующий id и прежние команды.`}]}),(0,b.jsx)(`p`,{children:`Пример с метками показывает причину изменения, а различие None и пустого списка объясняет условие выбора контейнера. Прослеживание передачи ссылок подготавливает работу обработчиков; различие break и return объясняет, где заканчивается команда и где появляется результат run.`}),(0,b.jsx)(`p`,{children:`Мы проверим и обычный вызов без аргумента, чтобы CLI продолжил запускаться привычным способом. Для наблюдения результата используем явный сценарий после определений функций, затем восстановим штатный конечный вызов. Импорт main.py, JSON и сохранение между процессами здесь не требуются.`}),(0,b.jsx)(r,{points:[(0,b.jsx)(b.Fragment,{children:`Изменяемый default вычисляется при определении функции и может быть общим для вызовов.`}),(0,b.jsx)(b.Fragment,{children:`None обозначает отсутствие переданного контейнера; пустой список остаётся настоящим входом.`}),(0,b.jsx)(b.Fragment,{children:`Один выбранный список проходит через обработчики без копии на каждую команду.`}),(0,b.jsx)(b.Fragment,{children:`break прекращает цикл, а return возвращает состояние из функции.`})]}),(0,b.jsx)(f,{text:`Применим договор run(tasks=None) к существующему Planner и проверим независимость обычных запусков и идентичность переданного списка.`})]})]})}export{x as Lesson22_1};